10→// Use an active state, but with a delay in unmounting to give exit transitions time to complete
11→export const useDelayedUnmount = (
12→  active: boolean,
13→  setActive: React.Dispatch<React.SetStateAction<boolean>>,
14→  unmountDelay = 3000, /*ms*/
15→): [boolean, React.Dispatch<React.SetStateAction<boolean>>] => {
16→  const [shouldMount, setShouldMount] = useDebounce(active, unmountDelay);
17→  
18→  const setActiveWithUnmountDelay = React.useCallback((active: React.SetStateAction<boolean>) => {
19→    setActive(active);
20→    if (active) { setShouldMount(true); } // Skip the delay when activating (should only be for deactivation)
21→  }, [setActive, setShouldMount]);
22→  
23→  React.useDebugValue(`Active: ${active} / Mounted: ${shouldMount}`);
24→  
25→  return [shouldMount, setActiveWithUnmountDelay];
26→};
