 8→export type UseFocusProps<T> = {
 9→  autoFocus?: undefined | boolean,
10→  onFocus?: undefined | ((event: React.FocusEvent<T>) => void),
11→  onBlur?: undefined | ((event: React.FocusEvent<T>) => void),
12→};
13→export const useFocus = <T extends HTMLElement>({ autoFocus = false, onFocus, onBlur }: UseFocusProps<T>) => {
14→  const ref = React.useRef<T>(null);
15→  
16→  const [isFocused, setIsFocused] = React.useState(autoFocus);
17→  
18→  React.useEffect(() => {
19→    if (ref.current) {
20→      if (isFocused) {
21→        ref.current.focus();
22→      } else {
23→        ref.current.blur();
24→      }
25→    }
26→  }, [isFocused]);
27→  
28→  const handleFocus = (event: React.FocusEvent<T>) => {
29→    setIsFocused(true);
30→    if (onFocus) {
31→      onFocus(event);
32→    }
33→  };
34→  
35→  const handleBlur = (event: React.FocusEvent<T>) => {
36→    setIsFocused(false);
37→    if (onBlur) {
38→      onBlur(event);
39→    }
40→  };
41→  
42→  return {
43→    ref,
44→    isFocused,
45→    handleFocus,
46→    handleBlur,
47→  };
48→};
