 5→import * as React from 'react';
 6→
 7→
 8→/**
 9→ * 
10→ * @param maxDuration 
11→ * @returns 
12→ */
13→export const useTypeAhead = (maxDuration = 400/*ms*/) => {
14→  const [sequence, setSequence] = React.useState<Array<string>>([]);
15→  const lastKeyPressTime = React.useRef(Date.now());
16→  
17→  const handleKeyDown = React.useCallback((event: React.KeyboardEvent) => {
18→    const now = Date.now();
19→    const shouldReset = now - lastKeyPressTime.current > maxDuration;
20→    lastKeyPressTime.current = now;
21→    
22→    setSequence((prevSequence) => {
23→      const currentSequence = shouldReset ? [] : prevSequence;
24→      
25→      // Ignore isolated space inputs, since we likely instead want this to trigger an action (e.g. clicking a button
26→      // or selecting a form input).
27→      if (event.key === ' ') { return currentSequence; }
28→      
29→      const isPrintable = event.key.length === 1; // For control characters, `key` will be a longer word (e.g. `Tab`)
30→      
31→      // Note: we want to:
32→      // - Allow 'Shift' (we don't want to block things like capitals or other shift keyboard layout characters)
33→      // - Allow Alt/AltGraph (commonly used for composition, e.g. Alt+Shift+2 could become "€").
34→      const hasModifier = (['Control', 'Meta'] as const).some(mod => event.getModifierState(mod));
35→      
36→      const isInput = event.target instanceof HTMLInputElement;
37→      
38→      if (!isPrintable || hasModifier || isInput) { return currentSequence; }
39→      
40→      event.preventDefault();
41→      event.stopPropagation();
42→      
43→      return [...currentSequence, event.key];
44→    });
45→  }, [maxDuration]);
46→  
47→  return { handleKeyDown, sequence };
48→};
