  7→
  8→export type ModalDialogRef = Readonly<{
  9→  id: string,
 10→  // Note: ideally we'd just have an `HTMLDialogElement` here without the `null` case. However, refs are not controlled
 11→  // (aren't synced with the render cycle), thus it may be safer to deal with this downstream at the use site.
 12→  dialogRef: React.RefObject<null | HTMLDialogElement>,
 13→}>;
 14→// Represents a stack of modal dialog elements that are currently open in the top layer
 15→export type ModalDialogStack = ReadonlyArray<ModalDialogRef>;
 16→
 17→export type ModalDialogStackSubscriber = (this: ModalDialogStackObservable, modalDialogStack: ModalDialogStack) => void;
 18→/** Observable for a `ModalDialogStack`, can be subscribed to to listen for updates. */
 19→export class ModalDialogStackObservable {
 20→  #subscribers: Set<ModalDialogStackSubscriber> = new Set();
 21→  #modalDialogStack: ModalDialogStack = [];
 22→  
 23→  /** Subscribe to updates. Returns a function to unsubscribe. */
 24→  subscribe(subscriber: ModalDialogStackSubscriber): () => void {
 25→    this.#subscribers.add(subscriber);
 26→    subscriber.call(this, this.#modalDialogStack); // Publish the current state
 27→    return () => { this.#subscribers.delete(subscriber); };
 28→  }
 29→  
 30→  /** Publish the current state to all subscribers. */
 31→  publish() {
 32→    for (const subscriber of this.#subscribers) {
 33→      subscriber.call(this, this.#modalDialogStack);
 34→    }
 35→  }
 36→  
 37→  getById(id: string): null | ModalDialogRef {
 38→    return this.#modalDialogStack.find(ref => ref.id === id) ?? null;
 39→  }
 40→  activeModalDialog(): null | ModalDialogRef {
 41→    return this.#modalDialogStack.at(-1) ?? null;
 42→  }
 43→  
 44→  activate(modalDialog: ModalDialogRef) {
 45→    // Note: make sure to filter out any existing items with the same ID. If a modal re-activates, then it should
 46→    // move to the top of the stack.
 47→    this.#modalDialogStack = [...this.#modalDialogStack.filter(ref => ref.id !== modalDialog.id), modalDialog];
 48→    this.publish();
 49→  }
 50→  deactivate(modalDialog: ModalDialogRef) {
 51→    this.#modalDialogStack = [...this.#modalDialogStack.filter(ref => ref.id !== modalDialog.id)];
 52→    this.publish();
 53→  }
 54→}
 55→
 56→/**
 57→ * A context object that captures information about the state of the top layer.
 58→ */
 59→export type TopLayerContext = {
 60→  modalDialogStack: ModalDialogStackObservable,
 61→};
 62→export const TopLayerContext = React.createContext<null | TopLayerContext>(null);
 63→
 64→/**
 65→ * React context provider that manages the state of the top layer.
 66→ */
 67→export const TopLayerManager = (props: React.PropsWithChildren) => {
 68→  const modalDialogStackRef = React.useRef<null | ModalDialogStackObservable>(null);
 69→  const modalDialogStack = modalDialogStackRef.current ?? new ModalDialogStackObservable(); // Lazy initialize
 70→  
 71→  const context = React.useMemo<TopLayerContext>(() => ({ modalDialogStack }), [modalDialogStack]);
 72→  
 73→  return (
 74→    <TopLayerContext value={context}>
 75→      {props.children}
 76→    </TopLayerContext>
 77→  );
 78→};
 79→
 80→/**
 81→ * Hook that is meant to be used in any component that renders a popover element. Used to track which popovers are
 82→ * currently open in the top layer.
 83→ */
 84→export const usePopoverTracker = (active: boolean) => {
 85→  const context = React.use(TopLayerContext);
 86→  
 87→  // When `active` changes, sync up with the context
 88→  React.useEffect(() => {
 89→    if (context === null) { return; } // May sometimes become `null` even if a Provider is present in the tree?
 90→    if (active) {
 91→      context.modalDialogStack.publish();
 92→    }
 93→  }, [context, active]); 
 94→};
 95→
 96→/**
 97→ * Hook that is meant to be used in any component that renders a modal `<dialog>` element. Used to track which
 98→ * modal dialogs are currently open in the top layer.
 99→ */
100→export const useModalDialogTracker = (active: boolean, dialogRef: React.RefObject<null | HTMLDialogElement>) => {
101→  const context = React.use(TopLayerContext);
102→  
103→  const id = React.useId();
104→  const ref = React.useMemo<ModalDialogRef>(() => ({ id, dialogRef }), [id, dialogRef]);
105→  
106→  // When `active` changes, sync up with the context
107→  React.useEffect(() => {
108→    if (context === null) { return; } // May sometimes become `null` even if a Provider is present in the tree?
109→    if (active) {
110→      context.modalDialogStack.activate(ref);
111→    } else {
112→      context.modalDialogStack.deactivate(ref);
113→    }
114→    
115→    // On unmount, deactivate
116→    return () => {
117→      context.modalDialogStack.deactivate(ref);
118→    };
119→  }, [context, active, ref]);
120→};
121→
122→/**
123→ * Returns the currently active modal `<dialog>` element, if any.
124→ */
125→export const useActiveModalDialog = (): null | ModalDialogRef => {
126→  const context = React.use(TopLayerContext);
127→  
128→  const [activeModalDialog, setActiveModalDialog] = React.useState<null | ModalDialogRef>(null);
129→  
130→  React.useEffect(() => {
131→    if (context === null) { return; } // May sometimes become `null` even if a Provider is present in the tree?
132→    return context.modalDialogStack.subscribe(function() {
133→      const newActiveModalDialog = this.activeModalDialog();
134→      if (newActiveModalDialog !== activeModalDialog) {
135→        setActiveModalDialog(newActiveModalDialog);
136→      }
137→    });
138→  }, [context, activeModalDialog]);
139→  
140→  return activeModalDialog ?? null;
141→};
